#!/usr/bin/env node
/**
 * lyric.js — tempel lirik custom di atas gambar, 1 file, by alfidev
 * WhatsApp: https://www.whatsapp.com/channel/0029VbCOLKRKrWQtIO1vzN0E
 *
 * Pakai:
 *   node lyric.js -t "baris 1|baris 2|baris 3" [-o out.png]      => base dari dalam code
 *   node lyric.js -i gambar.jpg -t "lirik" [-o out.png]           => base dari file
 *   node lyric.js -f lirik.txt [-o out.png]
 *
 * Posisi teks: bawah (default), tengah, atas. Warna putih + garis hitam biar kebaca.
 */

const fs = require('node:fs');
const path = require('node:path');
const { createCanvas, loadImage, GlobalFonts } = require('@napi-rs/canvas');

// ┌── embedded base image (gambar asli terlampir dalam code) ──────────────────────┐
const EMBEDDED_DATAURL = 'data:image/jpeg;base64,' + '';
// ── end embedded ───────────────────────────────────────────────────────────────┘

// font system biasa; kalau ada font di folder ini, dipakai juga
for (const f of fs.readdirSync(__dirname).filter((x) => /\.(ttf|otf)$/i.test(x))) {
  try { GlobalFonts.registerFromPath(path.join(__dirname, f)); } catch {}
}

function args(argv) {
  const a = { out: 'out.png', pos: 'bottom', size: 0, o: 0.72, img: null };
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i];
    if (k === '-i') a.img = argv[++i];
    else if (k === '-t') a.text = argv[++i];
    else if (k === '-f') a.file = argv[++i];
    else if (k === '-o') a.out = argv[++i];
    else if (k === '-n') a.size = +argv[++i];
    else if (k === '--pos') a.pos = argv[++i];
    else if (k === '--alpha') a.o = +argv[++i];
    else if (k === '-h' || k === '--help') a.help = true;
  }
  return a;
}

// pecah jadi baris nggak lebih lebar dari maxW
function wrap(ctx, text, maxW) {
  const out = [];
  for (const raw of String(text).split(/\r?\n/)) {
    const words = raw.split(/\s+/).filter(Boolean);
    if (!words.length) { out.push(''); continue; }
    let line = '';
    for (const w of words) {
      const test = line ? line + ' ' + w : w;
      if (ctx.measureText(test).width > maxW && line) { out.push(line); line = w; }
      else line = test;
    }
    out.push(line);
  }
  return out;
}

async function render({ img, text, out, size, pos, o }) {
  const base = await loadImage(img);
  const W = base.width, H = base.height;
  const canvas = createCanvas(W, H);
  const ctx = canvas.getContext('2d');
  ctx.drawImage(base, 0, 0, W, H);

  const maxW = W * 0.86;
  let fontSize = size || 54;
  let lh = fontSize * 1.38;
  let lines = wrap(ctx, text, maxW);

  // perlahanin kalau terlalu tinggi / encer-encer
  while (lines.length * lh > H * 0.88 && fontSize > 14) {
    fontSize -= 2;
    lh = fontSize * 1.4;
    lines = wrap(ctx, text, maxW);
  }

  const blockH = lines.length * lh;
  const zoneTop = pos === 'top' ? 0.06 : pos === 'center' ? 0.26 : 0.82;
  const zoneH = H * (pos === 'top' ? 0.52 : pos === 'center' ? 0.5 : 0.16);
  let startY = Math.max(zoneTop * H + (zoneH - blockH) / 2, fontSize + 6);

  // pita gelap tipis biar lirik kebaca di atas gambar
  if (o < 0.95) {
    const alpha = o < 0.3 ? 0.95 : o < 0.6 ? 0.8 : 0.66;
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    const pad = lh * 0.35;
    ctx.fillRect(0, startY - fontSize - pad, W, blockH + pad * 2);
  }

  ctx.font = `bold ${fontSize}px "DejaVu Sans", sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = Math.max(3, fontSize / 9);
  ctx.fillStyle = '#fff';
  ctx.shadowColor = 'rgba(0,0,0,0.8)';
  ctx.shadowBlur = Math.max(2, fontSize / 9);
  const cx = W / 2;
  lines.forEach((ln, i) => {
    const y = startY + i * lh;
    ctx.strokeText(ln, cx, y);
    ctx.fillText(ln, cx, y);
  });
  ctx.shadowColor = 'transparent';

  fs.writeFileSync(out, await canvas.encode('png'));
  return { out, W, H, lines: lines.length, fontSize };
}

async function main() {
  const a = args(process.argv.slice(2));
  if (a.help) {
    console.error('node lyric.js -t "baris1|baris2" [-i gambar.jpg] [-o out.png] [--pos bottom|center|top] [-n font] [--alpha 0-1]');
    process.exit(0);
  }
  let text = a.text;
  if (a.file) text = fs.readFileSync(a.file, 'utf8');
  if (a.text) text = String(text).split('|').join('\n').trim();
  else if (a.file) text = String(text).trim();
  if (!text) { console.error('lirik kosong. Pakai: node lyric.js -t "lirik" [-f lirik.txt]'); process.exit(1); }

  let src;
  if (a.img) {
    // base dari file sendiri (opsional)
    src = fs.readFileSync(a.img);
    src = 'data:image/jpeg;base64,' + Buffer.from(src).toString('base64');
  } else {
    // base dari dalam kode (gambar asli terlampir)
    src = EMBEDDED_DATAURL;
  }

  const r = await render({ img: src, text, out: a.out, size: a.size, pos: a.pos, o: a.o });
  console.log(JSON.stringify({ ok: true, ...r }));
}

main().catch((e) => { console.error('[!] ' + e.message); process.exit(1); });
